import * as THREE from 'three/webgpu';
import { color, uniform, vec2, vec3, mix, smoothstep, length, fract, abs, max, float, positionLocal, uv } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'rich-empty-state';
  const [px, py, pz] = config.scenePosition?.position || [0, 0, 0];
  group.position.set(px, py, pz);

  const W = 3.2, H = 2.2;

  // ---- Panel background: radial engineered gradient + hairline grid ----
  const centerColor = color('#14141a');
  const edgeColor = color('#0b0b10');
  const gridColor = color('#e8ecf2');
  const borderColor = color('#26262f');

  const uvNode = uv();
  const centered = uvNode.sub(vec2(0.5, 0.5));
  const dist = length(vec2(centered.x.mul(W), centered.y.mul(H)));
  const maxDist = float(Math.sqrt((W * 0.5) * (W * 0.5) + (H * 0.5) * (H * 0.5)));
  const t = dist.div(maxDist).clamp(0.0, 1.0);
  const gradientColor = mix(centerColor, edgeColor, t);

  // hairline grid at 0.25-unit pitch
  const pitch = 0.25;
  const gx = fract(centered.x.mul(W).div(pitch));
  const gy = fract(centered.y.mul(H).div(pitch));
  const lineWidth = 0.02;
  const lineX = smoothstep(0.0, lineWidth, gx).oneMinus().add(smoothstep(1.0 - lineWidth, 1.0, gx));
  const lineY = smoothstep(0.0, lineWidth, gy).oneMinus().add(smoothstep(1.0 - lineWidth, 1.0, gy));
  const gridMask = max(lineX, lineY).clamp(0.0, 1.0).mul(0.06);

  const withGrid = mix(gradientColor, gridColor, gridMask);

  // border hairline
  const edgeX = smoothstep(0.5 - 0.006 / W, 0.5, abs(centered.x));
  const edgeY = smoothstep(0.5 - 0.006 / H, 0.5, abs(centered.y));
  const borderMask = max(edgeX, edgeY);
  const finalColor = mix(withGrid, borderColor, borderMask);

  const panelMat = new THREE.MeshStandardNodeMaterial({ roughness: 0.7, metalness: 0.2 });
  panelMat.colorNode = finalColor;
  panelMat.transparent = true;

  const panelGeo = new THREE.PlaneGeometry(W, H, 1, 1);
  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.name = 'empty-state-panel';
  group.add(panel);

  // ---- Ghost preview: wireframe card + circle + bars ----
  const ghostGroup = new THREE.Group();
  ghostGroup.name = 'ghost-preview';
  ghostGroup.position.set(-0.75, 0.0, 0.001);

  const ghostMat = new THREE.LineBasicNodeMaterial({ transparent: true, opacity: 0.3 });
  ghostMat.colorNode = color('#e8ecf2');

  // wireframe card outline 1.1 x 1.4
  const cw = 1.1, ch = 1.4;
  const cardPts = [
    new THREE.Vector3(-cw / 2, -ch / 2, 0),
    new THREE.Vector3(cw / 2, -ch / 2, 0),
    new THREE.Vector3(cw / 2, ch / 2, 0),
    new THREE.Vector3(-cw / 2, ch / 2, 0),
    new THREE.Vector3(-cw / 2, -ch / 2, 0),
  ];
  const cardGeo = new THREE.BufferGeometry().setFromPoints(cardPts);
  const cardLine = new THREE.Line(cardGeo, ghostMat);
  ghostGroup.add(cardLine);

  // ghost dial circle 0.55 diameter
  const circlePts = [];
  const segs = 48;
  const r = 0.275;
  for (let i = 0; i <= segs; i++) {
    const a = (i / segs) * Math.PI * 2;
    circlePts.push(new THREE.Vector3(Math.cos(a) * r, Math.sin(a) * r + 0.15, 0));
  }
  const circleGeo = new THREE.BufferGeometry().setFromPoints(circlePts);
  const circleMat = new THREE.LineBasicNodeMaterial({ transparent: true, opacity: 0.22 });
  circleMat.colorNode = color('#e8ecf2');
  const circleLine = new THREE.Line(circleGeo, circleMat);
  ghostGroup.add(circleLine);

  // two ghost text bars 0.7w x 0.06h at 22%
  const barMat = new THREE.MeshBasicNodeMaterial({ transparent: true, opacity: 0.22 });
  barMat.colorNode = color('#e8ecf2');
  const barGeo = new THREE.PlaneGeometry(0.7, 0.06);
  const bar1 = new THREE.Mesh(barGeo, barMat);
  bar1.position.set(0, -0.45, 0);
  const bar2 = new THREE.Mesh(barGeo, barMat);
  bar2.position.set(0, -0.58, 0);
  ghostGroup.add(bar1, bar2);

  group.add(ghostGroup);

  // ---- Copy column ----
  const copyGroup = new THREE.Group();
  copyGroup.name = 'copy-column';
  copyGroup.position.set(0.75, 0.55, 0.001);

  const headline = ctx.fontAtlas.createText({
    text: 'Your ledger is empty.',
    font: 'Lora',
    fontWeight: 600,
    fontSize: 0.14,
    letterSpacing: -0.01,
    lineHeight: 1.15,
    color: '#e8ecf2',
    maxWidth: 1.4,
  });
  headline.name = 'headline';
  headline.position.set(0, 0, 0);
  copyGroup.add(headline);

  const body = ctx.fontAtlas.createText({
    text: 'Commissioned pieces and saved references will appear here once you begin.',
    font: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 0.055,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: '#e8ecf2',
    maxWidth: 1.4,
  });
  body.name = 'body';
  body.position.set(0, -0.32, 0);
  copyGroup.add(body);

  group.add(copyGroup);

  // ---- CTA button ----
  const ctaGroup = new THREE.Group();
  ctaGroup.name = 'cta-button';
  ctaGroup.position.set(0.75, -0.55, 0.001);

  const ctaW = 1.5, ctaH = 0.36;
  const ctaTop = color('#ff4450');
  const ctaBottom = color('#c1121f');
  const ctaUv = uv();
  const ctaGrad = mix(ctaBottom, ctaTop, ctaUv.y);

  const ctaMat = new THREE.MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.3 });
  ctaMat.colorNode = ctaGrad;
  ctaMat.emissiveNode = color('#ff2a38').mul(1.5);

  const ctaGeo = new THREE.PlaneGeometry(ctaW, ctaH);
  const ctaMesh = new THREE.Mesh(ctaGeo, ctaMat);
  ctaGroup.add(ctaMesh);

  const ctaLabel = ctx.fontAtlas.createText({
    text: 'BROWSE THE COLLECTION',
    font: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 0.045,
    letterSpacing: 0.08,
    lineHeight: 1,
    color: '#16161d',
    align: 'center',
  });
  ctaLabel.name = 'cta-label';
  ctaLabel.position.set(0, 0, 0.002);
  ctaGroup.add(ctaLabel);

  group.add(ctaGroup);

  // ---- Apply cinematic primitives (none configured, but respect contract) ----
  const primitiveList = config.cinematicPrimitives || [];
  primitiveList.forEach((primitive) => {
    if (ctx.primitives && ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  });

  // ---- Animations ----
  const timelines = [];

  // mount fade-up
  group.traverse((obj) => {
    if (obj.material) {
      obj.material.transparent = true;
    }
  });
  const mountState = { opacity: 0, y: 0.2 };
  group.position.y = py + 0.2;
  const initialOpacityTargets = [panelMat, ghostMat, circleMat, barMat, ctaMat];
  initialOpacityTargets.forEach((m) => { if (m) m.opacity = 0; });
  headline.material && (headline.material.opacity = 0);
  body.material && (body.material.opacity = 0);
  ctaLabel.material && (ctaLabel.material.opacity = 0);

  const mountTl = gsap.timeline();
  mountTl.to(group.position, {
    y: py,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);
  mountTl.to(mountState, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate: () => {
      panelMat.opacity = mountState.opacity;
      ghostMat.opacity = mountState.opacity * 0.3;
      circleMat.opacity = mountState.opacity * 0.22;
      barMat.opacity = mountState.opacity * 0.22;
      ctaMat.opacity = mountState.opacity;
      if (headline.material) headline.material.opacity = mountState.opacity;
      if (body.material) body.material.opacity = mountState.opacity;
      if (ctaLabel.material) ctaLabel.material.opacity = mountState.opacity;
    },
  }, 0);
  timelines.push(mountTl);

  // ghost breathe
  const breatheState = { opacity: 0.24 };
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.5 });
  breatheTl.to(breatheState, {
    opacity: 0.34,
    duration: 2.4,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    onUpdate: () => {
      ghostMat.opacity = breatheState.opacity;
    },
  });
  timelines.push(breatheTl);

  // ---- Interaction handlers: press-down on CTA ----
  const handlers = {};
  handlers.onPointerDown = (event) => {
    if (event?.target === ctaMesh || event?.object === ctaMesh) {
      gsap.to(ctaGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    }
  };
  handlers.onPointerUp = (event) => {
    gsap.to(ctaGroup.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.12,
      ease: 'back.out',
    });
  };

  group.userData.handlers = handlers;

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    [panelGeo, cardGeo, circleGeo, barGeo, ctaGeo].forEach((g) => g && g.dispose());
    [panelMat, ghostMat, circleMat, barMat, ctaMat].forEach((m) => m && m.dispose());
    if (headline.userData?.cleanup) headline.userData.cleanup();
    if (body.userData?.cleanup) body.userData.cleanup();
    if (ctaLabel.userData?.cleanup) ctaLabel.userData.cleanup();
  };

  return group;
}
